from functools import lru_cache
xs=[14,20,26,32,38,44,50]
active={(x,y) for y in [32,38,44] for x in xs}|{(x,50) for x in [14,20,26,32]}
pegs=frozenset([(38,32),(38,38),(44,38),(14,50),(20,50),(32,50)])
def moves(ps):
 for x,y in ps:
  for dx,dy in [(12,0),(-12,0),(0,12),(0,-12)]:
   m=(x+dx//2,y+dy//2); d=(x+dx,y+dy)
   if m in ps and d in active and d not in ps: yield (x,y),d,frozenset((ps-{(x,y),m})|{d})
@lru_cache(None)
def solve(ps):
 if len(ps)==1:return []
 for s,d,n in moves(ps):
  r=solve(n)
  if r is not None:return [(s,d)]+r
 return None
print(solve(pegs))

